WITH temp AS (
SELECT #{item} materialCod FROM dual
) SELECT l.SAP_CODE FINISH_SAP_CODE, c.SAP_CODE, l.EMBRYO_VERSION, l.CLAMPING_PRESSURE, l.CURING_TIME FROM t_product_construction_info c LEFT JOIN t_lh_tire_construction_info l ON c.EMBRYO_CODE = l.EMBRYO_CODE AND c.EMBRYO_VERSION = l.EMBRYO_VERSION AND l.DEL_FLAG = '0' WHERE l.SAP_CODE IN (SELECT materialCod FROM temp) AND c.DEL_FLAG = '0' ORDER BY EMBRYO_CODE, EMBRYO_VERSION

